1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
111	
112	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
113	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
114	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
115	// 不同岗位互不影响。
116	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
117		position = clean(position)
118		owner = clean(owner)
119		overlapNote = clean(overlapNote)
120		if err := requireNonEmpty("岗位", position); err != nil {
121			return Shift{}, err
122		}
123		if err := requireNonEmpty("负责人", owner); err != nil {
124			return Shift{}, err
125		}
126		if !end.After(start) {
127			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
128				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
129		}
130	
131		var created Shift
132		err := svc.store.mutate(func(d *Data) error {
133			var overlapping []Shift
134			for _, sh := range d.Shifts {
135				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
136					overlapping = append(overlapping, sh)
137				}
138			}
139			if len(overlapping) > 0 && overlapNote == "" {
140				ids := make([]string, len(overlapping))
141				for i, sh := range overlapping {
142					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
143				}
144				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
145					ErrOverlap, strings.Join(ids, "、"))
146			}
147	
148			d.ShiftSeq++
149			now := svc.now()
150			created = Shift{
151				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
152				Position:  position,
153				Owner:     owner,
154				Start:     start,
155				End:       end,
156				CreatedAt: now,
157			}
158			d.Shifts = append(d.Shifts, created)
159	
160			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
161			for _, sh := range overlapping {
162				if findNote(d, created.ID, sh.ID) != nil {
163					continue
164				}
165				d.NoteSeq++
166				x, y := notePair(created.ID, sh.ID)
167				d.Notes = append(d.Notes, OverlapNote{
168					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
169					Position:  position,
170					ShiftA:    x,
171					ShiftB:    y,
172					Note:      overlapNote,
173					CreatedAt: now,
174				})
175			}
176			return nil
177		})
178		if err != nil {
179			return Shift{}, err
180		}
181		// 返回独立副本：调用方保留的建立结果（关闭时间等指针字段）不与系统
182		// 保存的班次共享内存。
183		return cloneShift(created), nil
184	}
185	
186	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
187	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
188		note = clean(note)
189		if err := requireNonEmpty("重叠说明", note); err != nil {
190			return OverlapNote{}, err
191		}
192		if clean(shiftA) == clean(shiftB) {
193			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
194		}
195	
196		var saved OverlapNote
197		err := svc.store.mutate(func(d *Data) error {
198			sa, _ := findShift(d, clean(shiftA))
199			sb, _ := findShift(d, clean(shiftB))
200			if sa == nil || sb == nil {
201				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
202			}
203			if sa.Position != sb.Position {
204				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
205					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
206			}
207			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
208				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
209					ErrInvalidInput, sa.ID, sb.ID)
210			}
211			d.NoteSeq++
212			x, y := notePair(sa.ID, sb.ID)
213			saved = OverlapNote{
214				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
215				Position:  sa.Position,
216				ShiftA:    x,
217				ShiftB:    y,
218				Note:      note,
219				CreatedAt: svc.now(),
220			}
221			d.Notes = append(d.Notes, saved)
222			return nil
223		})
224		return saved, err
225	}
226	
227	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
228	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
229		shiftID = clean(shiftID)
230		content = clean(content)
231		constraints = clean(constraints)
232		followOwner = clean(followOwner)
233		if err := requireNonEmpty("事项内容", content); err != nil {
234			return Item{}, err
235		}
236		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
237			return Item{}, err
238		}
239		if !severity.valid() {
240			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
241		}
242	
243		var created Item
244		err := svc.store.mutate(func(d *Data) error {
245			sh, _ := findShift(d, shiftID)
246			if sh == nil {
247				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
248			}
249			if sh.Closed {
250				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
251			}
252			d.ItemSeq++
253			now := svc.now()
254			created = Item{
255				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
256				OriginShiftID:  sh.ID,
257				ShiftIDs:       []string{sh.ID},
258				CurrentShiftID: sh.ID,
259				Content:        content,
260				Severity:       severity,
261				Constraints:    constraints,
262				FollowOwner:    followOwner,
263				CreatedAt:      now,
264				Events: []ItemEvent{
265					{At: now, Kind: "created", Detail: "事项建立"},
266				},
267			}
268			d.Items = append(d.Items, created)
269			return nil
270		})
271		if err != nil {
272			return Item{}, err
273		}
274		// 返回独立副本：调用方保留的新增结果与系统保存的事项脱离，
275		// 改动结果不影响存储，也不会在后续正常保存时被带进存储。
276		return cloneItem(created), nil
277	}
278	
279	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
280	// 只有本地数据保存成功才算修改完成：写盘失败时内存变更随快照一并回滚，
281	// 返回错误与零值事项，不把尚未保存的新值当作修改结果。
282	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
283		itemID = clean(itemID)
284		content = clean(content)
285		constraints = clean(constraints)
286		followOwner = clean(followOwner)
287		if err := requireNonEmpty("事项内容", content); err != nil {
288			return Item{}, err
289		}
290		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
291			return Item{}, err
292		}
293		if !severity.valid() {
294			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
295		}
296	
297		var updated Item
298		err := svc.store.mutate(func(d *Data) error {
299			it, _ := findItem(d, itemID)
300			if it == nil {
301				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
302			}
303			sh, _ := findShift(d, it.CurrentShiftID)
304			if sh == nil || sh.Closed {
305				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
306					ErrShiftClosed, itemID, it.CurrentShiftID)
307			}
308			changes := []string{}
309			if it.Content != content {
310				changes = append(changes, "内容")
311			}
312			if it.Severity != severity {
313				changes = append(changes, "严重程度")
314			}
315			if it.Constraints != constraints {
316				changes = append(changes, "限制条件")
317			}
318			if it.FollowOwner != followOwner {
319				changes = append(changes, "后续负责人")
320			}
321			it.Content = content
322			it.Severity = severity
323			it.Constraints = constraints
324			it.FollowOwner = followOwner
325			it.Events = append(it.Events, ItemEvent{
326				At:     svc.now(),
327				Kind:   "updated",
328				Detail: "修改字段：" + joinOr(changes, "无变更"),
329			})
330			updated = *it
331			return nil
332		})
333		if err != nil {
334			// 保存失败时内存已回滚，不能把尚未保存的新值当作修改结果返回。
335			return Item{}, err
336		}
337		// 返回独立副本：调用方保留的修改结果不与系统保存的事项共享内存。
338		return cloneItem(updated), nil
339	}
340	
341	func joinOr(xs []string, or string) string {
342		if len(xs) == 0 {
343			return or
344		}
345		return strings.Join(xs, "、")
346	}
347	
348	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
349	// 只有本地数据保存成功才算关闭完成：写盘失败时内存变更随快照一并回滚，
350	// 返回错误与零值事项，不把尚未保存的关闭状态当作关闭结果。
351	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
352		itemID = clean(itemID)
353		operator = clean(operator)
354		if err := requireNonEmpty("操作人", operator); err != nil {
355			return Item{}, err
356		}
357	
358		var closed Item
359		err := svc.store.mutate(func(d *Data) error {
360			it, _ := findItem(d, itemID)
361			if it == nil {
362				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
363			}
364			if it.Closed {
365				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
366			}
367			sh, _ := findShift(d, it.CurrentShiftID)
368			if sh == nil || sh.Closed {
369				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
370					ErrShiftClosed, itemID, it.CurrentShiftID)
371			}
372			now := svc.now()
373			it.Closed = true
374			it.ClosedAt = &now
375			it.CloseOperator = operator
376			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
377			closed = *it
378			return nil
379		})
380		if err != nil {
381			// 保存失败时内存已回滚，不能把尚未保存的关闭状态当作关闭结果返回。
382			return Item{}, err
383		}
384		// 返回独立副本：调用方保留的关闭结果（含关闭时间）与系统保存的事项脱离；
385		// 班次结束后再改写这份结果中的关闭时刻，结束时记录里保留的仍是当时的值。
386		return cloneItem(closed), nil
387	}
388	
389	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
390	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
391	// 交接视为已完成，可以结束。
392	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
393	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
394	// 事项归属与已保存的处理经过。
395	// 返回的班次结果是成功结束时的独立副本（关闭时间与结束时记录均深拷贝）：
396	// 调用方为本地展示改动结果（实际结束时刻、事项内容、清单项、关闭时间等）
397	// 只影响手中的结果，不改变系统保存的结束时事实，也不随之后的正常保存被带进
398	// 存储；先取得的另一份结果同样互不影响。
399	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
400		shiftID = clean(shiftID)
401		var result Shift
402		err := svc.store.mutate(func(d *Data) error {
403			sh, _ := findShift(d, shiftID)
404			if sh == nil {
405				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
406			}
407			if sh.Closed {
408				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
409			}
410			for i := range d.Handovers {
411				h := &d.Handovers[i]
412				if h.ToShiftID == sh.ID && !h.Completed() {
413					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
414						ErrHandoverState, h.ID)
415				}
416			}
417			now := svc.now()
418			sh.Closed = true
419			sh.ClosedAt = &now
420	
421			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
422			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。每项指针
423			// （关闭时间）都复制一份：结束时记录保留这次成功结束时的事实，既不与
424			// 事项当前记录共享内存，也不与交给调用方的结果共享内存。
425			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
426			for i := range d.Items {
427				it := &d.Items[i]
428				if it.CurrentShiftID != sh.ID {
429					continue
430				}
431				record.Items = append(record.Items, CloseItemSnapshot{
432					ItemID:        it.ID,
433					Content:       it.Content,
434					Severity:      it.Severity,
435					Constraints:   it.Constraints,
436					FollowOwner:   it.FollowOwner,
437					Closed:        it.Closed,
438					ClosedAt:      cloneTimePtr(it.ClosedAt),
439					CloseOperator: it.CloseOperator,
440				})
441			}
442			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
443			sh.CloseRecord = record
444	
445			// 返回独立副本：调用方改写自己保留的结果不能影响系统保存的结束时记录。
446			result = cloneShift(*sh)
447			return nil
448		})
449		return result, err
450	}
451	
452	// CreateHandover 由交班班次向同岗位接班班次发起交接。
453	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
454	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
455	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
456	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
457	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
458	// 要求仅对首次发起生效。
459	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
460		fromShiftID = clean(fromShiftID)
461		toShiftID = clean(toShiftID)
462	
463		var result Handover
464		err := svc.store.mutate(func(d *Data) error {
465			from, _ := findShift(d, fromShiftID)
466			to, _ := findShift(d, toShiftID)
467			if from == nil {
468				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
469			}
470			if to == nil {
471				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
472			}
473			if from.ID == to.ID {
474				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
475			}
476			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
477			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
478			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
479			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
480			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
481			// 存在与交给自身的校验仍在其前。
482			for i := range d.Handovers {
483				if d.Handovers[i].FromShiftID == from.ID {
484					existing := &d.Handovers[i]
485					// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
486					// 不影响系统保存的原交接记录。
487					result = cloneHandover(*existing)
488					if existing.ToShiftID != to.ID {
489						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
490							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
491					}
492					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
493				}
494			}
495	
496			if from.Position != to.Position {
497				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
498					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
499			}
500	
501			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
502			// 交班班次已经结束，重叠区间须有说明。
503			if to.Closed {
504				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
505			}
506			if to.Start.Before(from.Start) {
507				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
508					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
509					from.ID, from.Start.Format(time.RFC3339))
510			}
511			if !from.Closed {
512				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
513					ErrShiftNotClosed, from.ID)
514			}
515			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
516				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
517					ErrOverlap, from.ID, to.ID)
518			}
519	
520			entries := []HandoverEntry{}
521			for i := range d.Items {
522				it := &d.Items[i]
523				if it.CurrentShiftID == from.ID && !it.Closed {
524					entries = append(entries, HandoverEntry{
525						ItemID:      it.ID,
526						Content:     it.Content,
527						Severity:    it.Severity,
528						Constraints: it.Constraints,
529						FollowOwner: it.FollowOwner,
530						Status:      EntryPending,
531					})
532				}
533			}
534			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
535	
536			d.HandoverSeq++
537			now := svc.now()
538			h := Handover{
539				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
540				Position:    from.Position,
541				FromShiftID: from.ID,
542				ToShiftID:   to.ID,
543				CreatedAt:   now,
544				Entries:     entries,
545			}
546			if len(entries) == 0 {
547				// 空清单直接完成。
548				h.CompletedAt = &now
549			}
550			d.Handovers = append(d.Handovers, h)
551			result = cloneHandover(h)
552			return nil
553		})
554		return result, err
555	}
