877	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
878	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
879	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
880	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
881	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
882	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
883	// 也不会改写这份报告；再次查询才反映最新内容。
884	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
885		shiftID = clean(shiftID)
886		d := &svc.store.data
887		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
888		sh, _ := findShift(d, shiftID)
889		if sh == nil {
890			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
891		}
892		rep.Shift = cloneShift(*sh)
893	
894		for _, n := range d.Notes {
895			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
896				rep.OverlapNotes = append(rep.OverlapNotes, n)
897			}
898		}
899		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
900	
901		switch {
902		case !sh.Closed:
903			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
904			rep.Items = currentItemsOfShift(d, sh.ID)
905		case sh.CloseRecord != nil:
906			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
907			rep.ItemsAtClose = true
908			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
909			for i, s := range sh.CloseRecord.Items {
910				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
911			}
912			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
913			for _, s := range rep.CloseItems {
914				if it, _ := findItem(d, s.ItemID); it != nil {
915					rep.LatestItems[s.ItemID] = cloneItem(*it)
916				}
917			}
918		default:
919			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
920			rep.HistoryIncomplete = true
921			rep.Items = currentItemsOfShift(d, sh.ID)
922		}
923		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
924		for i := range rep.Items {
925			rep.Items[i] = cloneItem(rep.Items[i])
926		}
927	
928		for i := range d.Handovers {
929			h := &d.Handovers[i]
930			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
931			if !involved {
932				continue
933			}
934			if h.FromShiftID == sh.ID {
935				cp := cloneHandover(*h)
936				rep.Outgoing = &cp
937			}
938			if h.ToShiftID == sh.ID {
939				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
940			}
941			for j := range h.Entries {
942				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
943					HandoverID: h.ID,
944					FromShift:  h.FromShiftID,
945					ToShift:    h.ToShiftID,
946					Entry:      cloneEntry(h.Entries[j]),
947				})
948			}
949		}
950		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
951		for k := range rep.Results {
952			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
953		}
954		return rep, nil
955	}
