	}
	if ok.CloseRecord.Items == nil || len(ok.CloseRecord.Items) != 0 {
		t.Fatalf("空清单班次的结束时记录应为空清单：%+v", ok.CloseRecord)
	}
	_ = time.Now
}
EOF
